DO $review$
DECLARE
 cid uuid := '35512cdd-3b6c-4039-b98d-cbd3ff8a6810';
 r jsonb; its jsonb; answers jsonb; corrections jsonb; answer_text text;
BEGIN
 SELECT checklist_rubric INTO r FROM public.case_answer_keys WHERE case_id=cid;
 IF r IS NULL OR jsonb_array_length(r->'items')<>16 OR NOT EXISTS(SELECT 1 FROM public.clinical_cases WHERE id=cid AND status='prereview') THEN RAISE EXCEPTION 'Soal atau daftar tilik berubah; peninjauan dibatalkan'; END IF;
 answers := $j$[
 "Selamat pagi Bu, saya dokter yang memeriksa Ibu. Saya pastikan identitas, jelaskan pemeriksaan, minta izin, menjaga privasi, dan melakukan kebersihan tangan. Inspeksi dilakukan berdiri bila aman; pemeriksaan kompresibilitas vena dapat dilakukan berbaring. Bila Ibu tidak mampu berdiri, saya gunakan posisi reverse Trendelenburg atau duduk dengan kaki menggantung.",
 "Saya inspeksi kedua tungkai dari depan dan belakang, mencari edema, varises, perubahan kulit dan ulkus aktif atau yang telah sembuh. Saya palpasi suhu, edema, nadi dorsalis pedis dan tibialis posterior, serta mencari nyeri, pucat, parestesia, paralisis, dingin, dan hilangnya nadi sebagai tanda iskemia akut.",
 "Jika diperlukan saya demonstrasikan tes Trendelenburg: elevasi tungkai untuk mengosongkan vena, pasang torniket di paha atas tanpa menghambat arteri, lalu pasien berdiri dengan bantuan. Pengisian cepat saat torniket masih terpasang dapat mengarah ke inkompetensi perforator; pengisian mendadak setelah torniket dilepas mengarah ke refluks superfisial proksimal. Tes ini memiliki keterbatasan dan lokalisasi dipastikan dengan DUS, bukan batas 35 detik.",
 "Saya gunakan USG B-mode, color dan pulsed-wave Doppler dengan probe linear sekitar 7–12 MHz, gel secukupnya, dan pengaturan kedalaman sesuai vena. Refluks dinilai berdiri dengan lutut sedikit fleksi bila aman; bila tidak mampu, posisi reverse Trendelenburg atau duduk digunakan dan dicatat.",
 "Saya mulai dari vena femoralis komunis, kemudian vena femoralis, poplitea, saphena magna beserta sambungan safenofemoral, dan saphena parva beserta sambungannya. Saya petakan vena superfisial dan dalam; vena femoralis termasuk sistem dalam, bukan vena superfisial.",
 "Pada B-mode transversal saya tekan probe secara bertahap untuk menilai kompresibilitas vena femoralis dan poplitea. Laporan menyatakan vena kompresibel penuh dan tidak tampak trombus pada segmen yang diperiksa. Ini tidak mendukung DVT pada segmen tersebut; bila kecurigaan klinis tetap tinggi, lakukan pemeriksaan lengkap atau ulang sesuai protokol.",
 "Diameter GSV yang diberikan adalah 5,4 mm. Saya catat lokasi dan posisi pengukuran, tempatkan sampel Doppler dalam lumen dan nilai fasifitas respirasi. Diameter saja tidak menentukan refluks; tidak ada satu batas normal 5 mm yang berlaku untuk semua lokasi dan pasien.",
 "Saya lakukan kompresi distal lalu pelepasan untuk memprovokasi aliran dan mengukur durasi aliran balik. Augmentasi positif mendukung aliran pada segmen yang diperiksa, tetapi tidak sendirian menyingkirkan obstruksi. Refluks femoralis 2700 ms dan GSV 1580 ms dicatat pada spektrum.",
 "Refluks patologis umumnya lebih dari 500 ms pada vena superfisial dan lebih dari 1000 ms pada vena femoralis atau poplitea. GSV 1580 ms dan femoralis 2700 ms keduanya patologis. Saya tidak memakai 2000 ms sebagai ambang umum untuk menyatakan GSV normal.",
 "D-dimer 250 tanpa satuan dan batas rujukan tidak dapat diinterpretasi sebagai negatif. D-dimer tidak menilai refluks kronik; penilaian DVT menggunakan probabilitas klinis dan ultrasonografi. ABI 1,02 dan nadi teraba mendukung perfusi arteri memadai untuk kompresi pada kasus ini. Bila ABI rendah, tekanan kompresi disesuaikan; ABI di bawah 0,6 atau tekanan pergelangan di bawah 60 mmHg merupakan alasan menghindari kompresi menetap kuat tanpa evaluasi spesialis.",
 "Diagnosisnya insufisiensi vena kronik tungkai kanan dengan ulkus vena yang telah sembuh dan keluhan simptomatik, CEAP C5s, As,d, Pr. Tidak ada bukti riwayat DVT atau perubahan post-trombotik sehingga saya tidak menyebut sindrom post-trombotik. Etiologi perlu dipastikan; En digunakan bila belum dapat diidentifikasi, dan Ep hanya bila evaluasi mendukung primer. Es hanya bila ada bukti penyebab sekunder.",
 "Bandingnya DVT akut, selulitis dan limfedema. DVT akut kurang didukung karena perjalanan kronik dan vena kompresibel pada segmen yang diperiksa; selulitis kurang didukung tanpa demam atau eritem hangat meluas. Limfedema dinilai dari distribusi edema dan tanda Stemmer; tidak adanya riwayat filaria saja tidak menyingkirkan limfedema.",
 "Saya anjurkan penurunan berat badan, berjalan dan latihan pompa betis, elevasi tungkai serta menghindari duduk atau berdiri statis lama. Dengan ABI 1,02, kompresi bawah lutut 20–40 mmHg dapat digunakan untuk edema, dipilih 30–40 mmHg bila ditoleransi pada riwayat ulkus, dengan penyesuaian kenyamanan dan kepatuhan. Perawatan kulit dan kompresi jangka panjang membantu mencegah ulkus berulang.",
 "Obat venoaktif seperti MPFF diosmin–hesperidin 500 mg dua kali sehari dapat dipertimbangkan untuk gejala, bukan pengganti kompresi atau perbaikan katup. Tidak ada indikasi antibiotik rutin untuk ulkus yang telah sembuh; antibiotik diberikan bila ada infeksi klinis. Antikoagulan tidak diberikan hanya karena refluks vena tanpa trombosis atau indikasi lain.",
 "Saya rujuk untuk pemetaan DUS dan pertimbangan ablasi endovenosa laser atau radiofrekuensi pada refluks GSV untuk mengurangi kekambuhan ulkus. Refluks dalam bukan otomatis kontraindikasi ablasi superfisial; obstruksi dan fungsi kolateral perlu dinilai. Skleroterapi terpandu USG dapat menjadi alternatif terpilih atau untuk tributari; laser transkutan untuk telangiektasia, bukan perforator. Ligation dan stripping dipertimbangkan bila terapi endovenosa tidak sesuai atau tidak tersedia.",
 "Bu, katup pembuluh balik Ibu kurang menutup sehingga darah menggenang dan dapat menimbulkan luka lagi. Gunakan stoking sesuai anjuran saat beraktivitas, rawat kulit, sering berjalan dan elevasikan kaki. Segera kembali bila bengkak mendadak nyeri, demam dengan kemerahan meluas, luka baru, atau sesak dan nyeri dada. Kontrol sekitar dua minggu untuk edema, kecocokan stoking dan rencana rujukan vaskular."
]$j$::jsonb;
 corrections := $j${
 "2":"Tes Trendelenburg sebagai pemeriksaan tambahan — demonstrasi pengosongan vena, torniket paha tanpa menghambat arteri, berdiri aman, interpretasi pengisian sebelum dan setelah pelepasan; sebut keterbatasan dan konfirmasi DUS. SKOR: 2 = teknik dan interpretasi benar atau menjelaskan DUS lebih diutamakan dengan alasan; 1 = sebagian benar; 0 = interpretasi terbalik atau tindakan tidak aman.",
 "3":"Persiapan DUS — probe linear sekitar 7–12 MHz, gel, B-mode/color/spektrum, posisi berdiri aman untuk refluks atau alternatif dependen bila tidak mampu. SKOR: 2 = alat dan posisi sesuai; 1 = sebagian; 0 = teknik tidak sesuai tanpa alasan.",
 "4":"Urutan vena — femoralis komunis, femoralis (vena dalam), poplitea, GSV/SFJ dan SSV/SPJ. SKOR: 2 = sistem dalam dan superfisial tercakup; 1 = sebagian; 0 = melewatkan sistem dalam.",
 "5":"Compression ultrasound — B-mode transversal, kompresi bertahap pada vena dalam, interpretasi kompresibel tanpa trombus pada segmen diperiksa dan pemeriksaan lanjut bila kecurigaan tinggi. SKOR: 2 = teknik serta interpretasi benar; 1 = sebagian; 0 = diagnosis hanya dari D-dimer.",
 "6":"Diameter dan spektrum — catat GSV 5,4 mm beserta lokasi/posisi, sampel dalam lumen, fasifitas respirasi, diameter tidak menjadi satu-satunya kriteria refluks. SKOR: 2 = pengukuran dan interpretasi benar; 1 = sebagian; 0 = menyimpulkan refluks hanya dari batas diameter 5 mm.",
 "8":"Ambang refluks — superfisial >500 ms, femoralis/poplitea >1000 ms; GSV 1580 ms dan femoralis 2700 ms patologis. SKOR: 2 = ambang dan kedua interpretasi benar; 1 = sebagian; 0 = GSV 1580 ms dianggap normal dengan ambang umum 2000 ms.",
 "9":"Penilaian DVT dan keamanan kompresi — probabilitas klinis serta CUS; D-dimer 250 tanpa satuan tidak dapat dinyatakan negatif; ABI 1,02 mendukung perfusi; sesuaikan kompresi pada gangguan arteri. SKOR: 2 = interpretasi aman; 1 = sebagian; 0 = DVT disingkirkan hanya dari D-dimer atau kompresi kuat pada iskemia berat.",
 "10":"Diagnosis dan CEAP — CVI kanan, C5s, As,d, Pr; tidak menyebut post-trombotik tanpa bukti; etiologi En bila belum teridentifikasi atau Ep dengan alasan, Es bila bukti sekunder. SKOR: 2 = klasifikasi klinis/anatomi/refluks serta etiologi beralasan; 1 = sebagian; 0 = C6 meskipun ulkus sembuh atau post-trombotik dipastikan tanpa bukti.",
 "11":"Diagnosis banding — DVT akut, selulitis, limfedema; gunakan perjalanan klinis, CUS, tanda infeksi dan karakteristik edema. SKOR: 2 = tiga banding dengan alasan; 1 = dua atau alasan parsial; 0 = tidak menilai alternatif.",
 "12":"Konservatif dan kompresi — penurunan BB, latihan/elevasi, perawatan kulit, kompresi 20–40 mmHg disesuaikan toleransi (30–40 mmHg layak pada riwayat ulkus), evaluasi arteri dan kepatuhan. SKOR: 2 = terapi inti dan keamanan benar; 1 = sebagian; 0 = tanpa kompresi atau mengabaikan iskemia berat.",
 "14":"Intervensi — pemetaan dan pertimbangan ablasi GSV laser/RFA, evaluasi refluks dalam dan obstruksi/kolateral, skleroterapi USG untuk indikasi terpilih, stripping bila endovenosa tidak sesuai. SKOR: 2 = rencana dan pilihan sesuai; 1 = sebagian; 0 = laser transkutan untuk perforator atau ablasi tanpa evaluasi anatomi."
 }$j$::jsonb;
 SELECT jsonb_agg((item || jsonb_build_object('id',COALESCE(item->>'id',gen_random_uuid()::text),'points',2,'answer',answers->>(n-1)::int)) || CASE WHEN corrections ? (n-1)::text THEN jsonb_build_object('text',corrections->>(n-1)::text) ELSE '{}'::jsonb END ORDER BY n) INTO its FROM jsonb_array_elements(r->'items') WITH ORDINALITY e(item,n);
 SELECT string_agg(value,E'\n\n' ORDER BY n) INTO answer_text FROM jsonb_array_elements_text(answers) WITH ORDINALITY e(value,n);
 r := r || jsonb_build_object('items',its,'enabled',true,'provided_to_candidate',$j$[
 {"label":"Anamnesis tambahan","value":"Keluhan kronik; duduk lama; luka tungkai bawah sudah menutup; tidak ada riwayat DVT yang diketahui, operasi tungkai, demam, sesak atau nyeri dada. Obat rutin tidak ada."},
 {"label":"Pemeriksaan fisik","value":"IMT 34; tanda vital dalam batas normal. Edema kanan, hiperpigmentasi pergelangan, ulkus lama sudah menutup. Tidak ada pus atau eritem hangat meluas. Nadi dorsalis pedis dan tibialis posterior teraba kuat."},
 {"label":"ABI dan laboratorium","value":"ABI kanan 1,02. D-dimer 250; satuan dan batas rujukan tidak tersedia, sehingga jangan diinterpretasi negatif hanya dari angka ini."}
 ]$j$::jsonb,'review_notes','Ditinjau 10 Nov 2026. Tidak ada bukti post-trombotik; diameter saja tidak menentukan refluks; Trendelenburg bukan pengganti DUS. Laporan teks adalah bahan ujian oral board; media asli belum tersedia. Penilaian menerima padanan klinis benar, bukan hafalan kata persis.');
 r := jsonb_set(r,'{digital_properties,2,value}',to_jsonb('GSV kanan diameter 5,4 mm; lokasi/posisi pengukuran tidak dicantumkan. Vena kompresibel, tidak tampak trombus. Refluks 1580 ms. Diameter saja tidak menentukan diagnosis refluks.'::text));
 r := jsonb_set(r,'{digital_properties,3,value}',to_jsonb('Laporan teks DUS: vena femoralis dan poplitea kompresibel tanpa trombus pada segmen diperiksa; augmentasi positif; refluks femoralis 2700 ms dan GSV 1580 ms. ABI 1,02. D-dimer 250 tanpa satuan/batas rujukan.'::text));
 UPDATE public.case_answer_keys SET answer_key_text=answer_text,checklist_rubric=r WHERE case_id=cid;
 UPDATE public.clinical_cases SET title='Vascular — Insufisiensi Vena Kronik Tungkai Kanan: Pemeriksaan, DUS dan CEAP',initial_prompt='Seorang wanita 55 tahun datang dengan tungkai kanan terasa berat, bengkak dan kram. Anda bertugas menilai pasien di klinik vaskular.',questions_text=E'1. Jelaskan persiapan dan pemeriksaan fisik vaskular yang akan Anda lakukan.\n2. Jelaskan teknik pemeriksaan DUS vena dan interpretasikan hasil yang diberikan setelah Anda meminta pemeriksaan.\n3. Tentukan diagnosis, klasifikasi CEAP, dan diagnosis banding dengan alasannya.\n4. Susun tatalaksana konservatif, obat dan pertimbangan intervensi.\n5. Sampaikan edukasi dan rencana tindak lanjut kepada pasien.',exam_mode='oral_board',time_limit_seconds=600,reading_time_seconds=90,answer_key_text=answer_text,properties=ARRAY(SELECT jsonb_array_elements_text(r->'properties')),checklist_rubric=jsonb_build_object('enabled',true,'items',(SELECT jsonb_agg(item-'answer' ORDER BY n) FROM jsonb_array_elements(its) WITH ORDINALITY e(item,n))),status='published',reviewed_at=now() WHERE id=cid AND status='prereview';
END $review$;